/// <summary>
/// MPJ_5904_ALMSupplierVolumetricRebates
/// Form handler for <c>VendTrans</c> form
/// </summary>
class METVendTransFormHandler
{
}

Method.Source:
   /// <summary>
   /// MPJ_5904_ALMSupplierVolumetricRebates
   /// </summary>
   /// <param name="sender">VendTrans datasource</param>
   /// <param name="e"><c>VendTrans</c> form arguments</param>
   [FormDataSourceEventHandler(formDataSourceStr(VendTrans, VendTrans), FormDataSourceEventType::Initialized),
       SuppressBPWarning('BPParameterNotUsed', 'Standard parameter')]
   public static void VendTrans_OnInitialized(FormDataSource sender, FormDataSourceEventArgs e)
   {
       FormRun                 vendTransForm           = sender.formRun();

       if(vendTransForm.args().dataset() == tableNum(METALMSupplierVolumetricRebateHeader))
       {
           METALMSupplierVolumetricRebateHeader rebateHeader = vendTransForm.args().record();
           if (rebateHeader)
           {
               sender.query().dataSourceTable(tableNum(VendTrans)).addRange(fieldNum(VendTrans, Invoice)).value(rebateHeader.InvoiceId);
               sender.query().dataSourceTable(tableNum(VendTrans)).addRange(fieldNum(VendTrans, AccountNum)).value(rebateHeader.VendorAccount);
           }
       }
   }
